"""Two additive tables for the first production workflow; shared jobs own state."""
from __future__ import annotations

import json
from pathlib import Path

from core.config import DATA_DIR
from core.db import db_conn

ROOT = Path(DATA_DIR) / "production"

def asset_path(asset_id: str) -> Path:
    # IDs are content hashes generated by this service, never client paths.
    if len(asset_id) != 64 or any(c not in "0123456789abcdef" for c in asset_id):
        raise ValueError("Unknown media asset.")
    return ROOT / "assets" / asset_id / "source.mp4"


def get_asset(asset_id: str) -> dict:
    with db_conn() as conn:
        row = conn.execute("SELECT * FROM media_assets WHERE id=?", (asset_id,)).fetchone()
    if row is None:
        raise ValueError("Media asset not found.")
    data = dict(row)
    data.update(json.loads(data.pop("metadata_json")))
    with db_conn() as conn:
        data['use_count'] = conn.execute('SELECT COUNT(*) FROM production_asset_usage WHERE asset_id=?', (asset_id,)).fetchone()[0]
    return data


def get_run(run_id: str) -> dict:
    with db_conn() as conn:
        row = conn.execute(
            "SELECT r.*, j.status, j.error, j.created_at, j.updated_at "
            "FROM production_runs r JOIN jobs j ON j.id=r.id WHERE r.id=?", (run_id,),
        ).fetchone()
    if row is None:
        raise ValueError("Production task not found.")
    data = dict(row)
    for name in ("plan", "steps", "artifacts"):
        data[name] = json.loads(data.pop(name + "_json"))
    return data


def set_step(run_id: str, name: str, status: str) -> None:
    with db_conn() as conn:
        row = conn.execute("SELECT steps_json FROM production_runs WHERE id=?", (run_id,)).fetchone()
        steps = json.loads(row[0])
        steps[name] = status
        conn.execute("UPDATE production_runs SET steps_json=? WHERE id=?", (json.dumps(steps), run_id))


def finish_active_steps(run_id: str, status: str) -> None:
    for name, state in get_run(run_id)["steps"].items():
        if state == "running":
            set_step(run_id, name, status)
